import{_ as o,o as t,c as i,ae as e}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"iCost 내역 가져오기","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/08-icost-bill-import-guide.md","filePath":"v1/ko/guide/08-icost-bill-import-guide.md"}'),l={name:"v1/ko/guide/08-icost-bill-import-guide.md"};function r(s,a,n,c,d,h){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="icost-내역-가져오기" tabindex="-1">iCost 내역 가져오기 <a class="header-anchor" href="#icost-내역-가져오기" aria-label="Permalink to &quot;iCost 내역 가져오기&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>Koala는 iCost의 <strong>Excel 내보내기</strong>(<code>.xlsx</code> / <code>.xls</code>)를 가져올 수 있습니다. iCost의 CSV는 지원하지 않습니다.</p><h2 id="📤-icost-내보내기-요약" tabindex="-1">📤 iCost 내보내기(요약) <a class="header-anchor" href="#📤-icost-내보내기-요약" aria-label="Permalink to &quot;📤 iCost 내보내기(요약)&quot;">​</a></h2><p>iCost 설정/더보기에서 내보내기(데이터 내보내기)를 찾아 형식을 <strong>Excel</strong>로 선택한 뒤 파일을 저장합니다.</p><h2 id="📥-koala-가져오기" tabindex="-1">📥 Koala 가져오기 <a class="header-anchor" href="#📥-koala-가져오기" aria-label="Permalink to &quot;📥 Koala 가져오기&quot;">​</a></h2><ol><li>설정 → 내역 가져오기</li><li>가져오기 소스: <strong>iCost</strong></li><li>Excel 파일 선택 → 장부 선택</li><li>파싱 → 미리보기 → 가져오기</li></ol><h2 id="⚠️-참고" tabindex="-1">⚠️ 참고 <a class="header-anchor" href="#⚠️-참고" aria-label="Permalink to &quot;⚠️ 참고&quot;">​</a></h2><ul><li>파싱은 헤더 행에 「日期」가 포함되어 있다고 가정합니다. 내보내기 언어를 선택할 수 있다면 중국어 헤더로 내보내는 것을 권장합니다.</li><li>같은 파일을 중복으로 가져오면 내역이 중복 생성될 수 있습니다.</li></ul><hr><p><strong>마지막 업데이트</strong>: 2026년 4월</p>',11)])])}const p=o(l,[["render",r]]);export{_ as __pageData,p as default};
